// Compact list of unread emails for the model (preview only, not full bodies).
const mails = $input.all().map(i => i.json).filter(m => m.id);
if (!mails.length) return [{ json: { empty: true } }];
const list = mails.map((m, n) =>
  `#${n + 1} | from: ${m.from?.emailAddress?.name ?? ''} <${m.from?.emailAddress?.address ?? ''}> | ` +
  `subject: ${m.subject ?? ''} | importance: ${m.importance ?? 'normal'} | received: ${m.receivedDateTime ?? ''}\n` +
  `${String(m.bodyPreview ?? '').replace(/\s+/g, ' ').slice(0, 400)}`
).join('\n\n');
return [{ json: { empty: false, count: mails.length, list } }];

const schema = {
  type: 'object', additionalProperties: false,
  properties: {
    headline: { type: 'string' },
    urgent: { type: 'array', items: { type: 'object', additionalProperties: false,
      properties: { email: { type: 'integer' }, why: { type: 'string' }, next_step: { type: 'string' } },
      required: ['email', 'why', 'next_step'] } },
    reply_today: { type: 'array', items: { type: 'object', additionalProperties: false,
      properties: { email: { type: 'integer' }, what_they_need: { type: 'string' } },
      required: ['email', 'what_they_need'] } },
    fyi: { type: 'array', items: { type: 'object', additionalProperties: false,
      properties: { email: { type: 'integer' }, one_line: { type: 'string' } },
      required: ['email', 'one_line'] } },
  },
  required: ['headline', 'urgent', 'reply_today', 'fyi'],
};

return [{ json: {
  ...$json,
  openai_payload: {
    model: $env.OPENAI_MODEL || 'gpt-5.6-luna',
    instructions: 'You prepare a morning email briefing for a busy professional. Group the emails: urgent (needs action today, blocking someone, deadlines, angry customers), reply_today, and fyi (newsletters, notifications, no action). ' + 'Refer to emails by their #number. Be concise and write in the language set in BRIEFING_LANGUAGE: ' + ($env.BRIEFING_LANGUAGE || 'Spanish') + '.',
    input: `${$json.count} unread emails:\n\n${$json.list}`,
    text: { format: { type: 'json_schema', name: 'email_digest', strict: true, schema } },
  },
} }];

function parseResponse(res) {
  const message = (res.output || []).find(o => o.type === 'message');
  const part = message?.content?.find(c => c.type === 'output_text' || c.type === 'refusal');
  if (!part || part.type === 'refusal') throw new Error('The model returned no usable answer: ' + JSON.stringify(res).slice(0, 300));
  return JSON.parse(part.text);
}

// Build the Teams message; subjects and senders come from the source emails, not from the model.
const d = parseResponse($json);
const mails = $('Unread emails since yesterday').all().map(i => i.json);
const ref = n => {
  const m = mails[n - 1];
  return m ? `<b>${m.from?.emailAddress?.name ?? ''}</b>: ${m.subject ?? ''}` : `#${n}`;
};
const section = (title, rows) => rows.length ? `<h3>${title}</h3><ul>${rows.join('')}</ul>` : '';

const html = `<p>☀️ <b>${d.headline}</b> (${mails.length} unread)</p>` +
  section('🔴 Urgent', d.urgent.map(u => `<li>${ref(u.email)}<br>${u.why} → <i>${u.next_step}</i></li>`)) +
  section('🟡 Reply today', d.reply_today.map(r => `<li>${ref(r.email)}: ${r.what_they_need}</li>`)) +
  section('⚪ FYI', d.fyi.map(f => `<li>${ref(f.email)}: ${f.one_line}</li>`));
return [{ json: { html } }];
